+.settings-dashboard {
+    display: flex;
+    gap: 0;
+    min-height: 600px;
+}
+
+/* Sidebar */
+.settings-sidebar {
+    width: 220px;
+    flex-shrink: 0;
+    background: #f8f9fa;
+    border-right: 1px solid #dee2e6;
+    padding: 1rem 0;
+}
+
+.sidebar-title {
+    padding: 0 1rem 0.75rem;
+    margin: 0;
+    font-weight: 600;
+    color: #495057;
+    border-bottom: 1px solid #dee2e6;
+}
+
+.settings-sidebar .nav-link {
+    display: flex;
+    align-items: center;
+    gap: 0.5rem;
+    padding: 0.6rem 1rem;
+    color: #495057;
+    border: none;
+    background: none;
+    width: 100%;
+    text-align: left;
+    cursor: pointer;
+    transition: background-color 0.15s, color 0.15s;
+    border-left: 3px solid transparent;
+}
+
+.settings-sidebar .nav-link:hover {
+    background: #e9ecef;
+    color: #212529;
+}
+
+.settings-sidebar .nav-link.active {
+    background: #e7f1ff;
+    color: #0d6efd;
+    font-weight: 600;
+    border-left-color: #0d6efd;
+}
+
+.sidebar-icon {
+    font-size: 1.1rem;
+}
+
+/* Content area */
+.settings-content {
+    flex: 1;
+    padding: 1.5rem 2rem;
+    min-width: 0;
+}
+
+.settings-section h3 {
+    margin-bottom: 1.25rem;
+    padding-bottom: 0.5rem;
+    border-bottom: 1px solid #dee2e6;
+}
+
+/* Profile */
+.profile-layout {
+    display: flex;
+    gap: 2rem;
+}
+
+.avatar-area {
+    flex-shrink: 0;
+    width: 160px;
+    text-align: center;
+}
+
+.avatar-img {
+    width: 120px;
+    height: 120px;
+    border-radius: 50%;
+    object-fit: cover;
+    border: 3px solid #dee2e6;
+    margin-bottom: 0.5rem;
+}
+
+.profile-fields {
+    flex: 1;
+}
+
+/* Appearance preview */
+.appearance-preview {
+    max-width: 400px;
+    transition: all 0.2s ease;
+}
+
+.preview-label {
+    font-weight: 600;
+    margin-bottom: 0.5rem;
+    font-size: 0.85rem;
+    text-transform: uppercase;
+    letter-spacing: 0.05em;
+    opacity: 0.7;
+}
+
+/* Toast fade-in animation */
+.fade-in {
+    animation: fadeIn 0.3s ease-in;
+}
+
+@keyframes fadeIn {
+    from { opacity: 0; transform: translateY(-4px); }
+    to   { opacity: 1; transform: translateY(0); }
+}
+
+/* Change password panel */
+.change-password-panel .card {
+    max-width: 450px;
+    margin-top: 0.25rem;
+}
+
+/* Modal backdrop fix */
+.modal-backdrop.show {
+    position: fixed;
+    top: 0; left: 0; right: 0; bottom: 0;
+    background: rgba(0,0,0,0.5);
+    z-index: 1040;
+}
+
+.modal.d-block {
+    z-index: 1050;
+}
+
+/* Responsive */
+@media (max-width: 768px) {
+    .settings-dashboard {
+        flex-direction: column;
+    }
+    .settings-sidebar {
+        width: 100%;
+        border-right: none;
+        border-bottom: 1px solid #dee2e6;
+    }
+    .settings-sidebar .nav {
+        flex-direction: row;
+        overflow-x: auto;
+    }
+    .settings-sidebar .nav-link {
+        border-left: none;
+        border-bottom: 3px solid transparent;
+    }
+    .settings-sidebar .nav-link.active {
+        border-left-color: transparent;
+        border-bottom-color: #0d6efd;
+    }
+    .profile-layout {
+        flex-direction: column;
+    }
+    .settings-content {
+        padding: 1rem;
+    }
+}
+

